// Normalize webhook body (topic + range) for digest query.
// When triggered by Manual/Schedule there is no body → use defaults.
// Webhook puts POST body under .body; also check root and .query.
// topicSlug uses '' (not null) because n8n drops null from queryParameters.
const item = $input.first();
const raw = item?.json || {};
const body = raw.body || raw;
const topicRaw = body.topicSlug ?? body.topic ?? raw.topicSlug ?? raw.topic ?? body.query?.topic ?? raw.query?.topic;
const topicSlug = topicRaw != null && String(topicRaw).trim() ? String(topicRaw).trim() : '';
const range = (body.range || body.query?.range || raw.range || '1w').toString().toLowerCase().trim();
let days = 7;
if (range === '2w') days = 14;
else if (range === '1d') days = 1;
else if (range === '3d') days = 3;
return [{ json: { days, topicSlug } }];

// Replicate weeklyDigest.js generateMarkdown() logic
const articles = $input.all().map(i => i.json).filter(a => a.id || a.title);

function formatDate(date) {
  return new Date(date).toLocaleDateString('en-US', {
    weekday: 'long', year: 'numeric', month: 'long', day: 'numeric'
  });
}

function formatDateShort(date) {
  return new Date(date).toLocaleDateString('en-US', {
    month: 'short', day: 'numeric', year: 'numeric'
  });
}

const endDate = new Date();
const startDate = new Date();
startDate.setDate(startDate.getDate() - 7);

const lines = [];

// Header
lines.push('# \u{1F4F0} AI News Weekly Digest');
lines.push('');
lines.push(`**${formatDate(startDate)} \u2014 ${formatDate(endDate)}**`);
lines.push('');

const uniqueSources = new Set(articles.map(a => a.source));
lines.push(`> ${articles.length} articles from ${uniqueSources.size} sources`);
lines.push('');
lines.push('---');
lines.push('');

if (articles.length === 0) {
  lines.push('_No articles found for this period._');
} else {
  // Group by category
  const grouped = {};
  for (const article of articles) {
    const cat = article.category || 'general';
    if (!grouped[cat]) grouped[cat] = [];
    grouped[cat].push(article);
  }

  // Sort categories by article count descending
  const sortedCategories = Object.entries(grouped).sort(
    (a, b) => b[1].length - a[1].length
  );

  for (const [category, catArticles] of sortedCategories) {
    const displayCat = category.charAt(0).toUpperCase() + category.slice(1);
    lines.push(`## ${displayCat} (${catArticles.length})`);
    lines.push('');

    // Sort by published date descending within category
    catArticles.sort((a, b) => new Date(b.published_at) - new Date(a.published_at));

    for (const article of catArticles) {
      const date = article.published_at ? formatDateShort(article.published_at) : 'Date N/A';
      const summary = article.summary
        ? article.summary.slice(0, 200) + (article.summary.length > 200 ? '...' : '')
        : '_No summary available._';

      lines.push(`### [${article.title}](${article.url})`);
      lines.push('');
      lines.push(`\u{1F4C5} ${date} \u00B7 \u{1F4E1} ${article.source}`);
      lines.push('');
      lines.push(summary);
      lines.push('');
    }

    lines.push('---');
    lines.push('');
  }
}

// Footer
lines.push(`_Generated on ${formatDate(new Date())} by AI News Digest._`);

const markdown = lines.join('\n');

return [{
  json: {
    markdown,
    articleCount: articles.length,
    sourceCount: new Set(articles.map(a => a.source)).size,
    categoryCount: new Set(articles.map(a => a.category || 'general')).size,
    period: `${formatDateShort(startDate)} - ${formatDateShort(endDate)}`,
    timestamp: new Date().toISOString()
  }
}];

const data = $('Generate Markdown Digest').first().json;

return [{
  json: {
    message: `Weekly digest generated. ${data.articleCount} articles across ${data.categoryCount} categories from ${data.sourceCount} sources.`,
    articleCount: data.articleCount,
    period: data.period,
    markdown: data.markdown,
    timestamp: data.timestamp
  }
}];
